import { Menu } from "lucide-react";
import { useEffect, useState } from "react";
import { useLocation, useSearchParams } from "react-router-dom";
import { SplitText } from "../reactbits/vendor";
import {
  WoodenBookshelf,
  type ShelfDrawerId,
} from "./WoodenBookshelf";

export function HomeLobby() {
  const [searchParams] = useSearchParams();
  const location = useLocation();
  const [shelfAction, setShelfAction] = useState(0);
  const drawerParam = searchParams.get("drawer");
  const initialDrawer: ShelfDrawerId | null =
    drawerParam === "notes" ||
    drawerParam === "materials" ||
    drawerParam === "collection"
      ? drawerParam
      : null;
  const initialBookId = searchParams.get("book");

  useEffect(() => {
    const handleShelfAction = () => setShelfAction((value) => value + 1);
    window.addEventListener("inkflow:shelf-action", handleShelfAction);
    return () =>
      window.removeEventListener("inkflow:shelf-action", handleShelfAction);
  }, []);

  return (
    <div className="home-lobby home-lobby--shelf">
      <header className="home-lobby__brand-dock">
        <button
          type="button"
          className="home-lobby__brand home-lobby__brand--compact home-lobby__brand--menu"
          aria-label="打开功能菜单"
          aria-haspopup="menu"
          onClick={() => window.dispatchEvent(new Event("inkflow:open-menu"))}
        >
          <span className="home-lobby__brand-mark" aria-hidden="true">
            <img src="/inkflow-logo.png" alt="" />
            <span className="home-lobby__brand-menuGlyph">
              <Menu size={11} strokeWidth={2.6} />
            </span>
          </span>
          <span>
            <SplitText
              tag="strong"
              text="InkFlow"
              className="home-lobby__brand-title"
              delay={42}
              duration={0.56}
              ease="power3.out"
              splitType="chars"
              from={{ opacity: 0, y: 20, rotateX: -32 }}
              to={{ opacity: 1, y: 0, rotateX: 0 }}
              threshold={0}
              rootMargin="0px"
              textAlign="left"
            />
            <small>Moonlit reading room</small>
          </span>
        </button>
      </header>

      <main className="home-lobby__main home-lobby__main--shelf home-lobby__main--study-room">
        <header className="home-lobby__room-head">
          <span className="home-lobby__room-heading">
            <span className="eyebrow">Moon · Piano · Quiet reading</span>
            <small>月灰琴书架 · 我的英语学习空间</small>
          </span>
        </header>

        <WoodenBookshelf
          actionKey={`${location.key}:${shelfAction}`}
          initialDrawer={initialDrawer}
          initialBookId={initialBookId}
        />
      </main>
    </div>
  );
}
