export type ReaderAnnotationType = "underline" | "highlight" | "sentence";
export type ReaderAnnotations = Record<string, ReaderAnnotationType>;

const STORAGE_PREFIX = "inkflow.reader.annotations.";

export function loadReaderAnnotations(bookId: string): ReaderAnnotations {
  if (typeof localStorage === "undefined") return {};
  try {
    const parsed = JSON.parse(
      localStorage.getItem(`${STORAGE_PREFIX}${bookId}`) ?? "{}",
    );
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

export function saveReaderAnnotations(
  bookId: string,
  annotations: ReaderAnnotations,
) {
  if (typeof localStorage === "undefined") return;
  localStorage.setItem(
    `${STORAGE_PREFIX}${bookId}`,
    JSON.stringify(annotations),
  );
}

export function splitReaderSentences(paragraph: string) {
  const matches = paragraph.match(/[^.!?]+[.!?]?/g) ?? [paragraph];
  return matches.map((sentence) => sentence.trim()).filter(Boolean);
}
