import { gsap } from "gsap";
import { useEffect, useRef, useState } from "react";
import { usePrefersReducedMotion } from "../../motion/usePrefersReducedMotion";
import "./site-intro.css";

const SESSION_KEY = "inkflow.intro.seen";

export function SiteIntro() {
  const prefersReducedMotion = usePrefersReducedMotion();
  const rootRef = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(() => {
    if (typeof sessionStorage === "undefined") return true;
    return sessionStorage.getItem(SESSION_KEY) !== "1";
  });

  useEffect(() => {
    if (!visible) return undefined;
    sessionStorage.setItem(SESSION_KEY, "1");
    if (prefersReducedMotion) {
      setVisible(false);
      return undefined;
    }
    const root = rootRef.current;
    if (!root) return undefined;

    const timeline = gsap.timeline({
      defaults: { ease: "power3.out" },
      paused: true,
      onComplete: () => setVisible(false),
    });
    timeline
      .fromTo(
        root.querySelector(".site-intro__wash"),
        { clipPath: "ellipse(0% 0% at 86% 50%)" },
        {
          clipPath: "ellipse(120% 130% at 86% 50%)",
          duration: 0.82,
          ease: "power4.out",
        },
      )
      .fromTo(
        root.querySelectorAll(".site-intro__staff-line"),
        { scaleX: 0, transformOrigin: "left center" },
        { scaleX: 1, duration: 0.54, stagger: 0.045 },
        "-=0.48",
      )
      .fromTo(
        root.querySelectorAll(".site-intro__note"),
        {
          opacity: 0,
          x: 150,
          y: (index: number) => 42 + index * 18,
          rotate: (index: number) => -12 + index * 7,
          scale: 0.42,
        },
        {
          opacity: 1,
          x: 0,
          y: 0,
          rotate: (index: number) => -7 + index * 4,
          scale: 1,
          duration: 0.7,
          stagger: 0.085,
          ease: "back.out(1.5)",
        },
        "-=0.36",
      )
      .fromTo(
        root.querySelector(".site-intro__word"),
        { yPercent: 118, rotate: 1.5, opacity: 0 },
        { yPercent: 0, rotate: 0, opacity: 1, duration: 0.74 },
        "-=0.68",
      )
      .fromTo(
        root.querySelector(".site-intro__tagline"),
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 0.48 },
        "-=0.32",
      )
      .fromTo(
        root.querySelector(".site-intro__eyebrow"),
        { opacity: 0, x: -14 },
        { opacity: 1, x: 0, duration: 0.38 },
        "-=0.42",
      )
      .to(
        root.querySelectorAll(".site-intro__note"),
        {
          y: -36,
          rotate: (index: number) => -4 + index * 6,
          duration: 0.48,
          stagger: 0.035,
        },
        "+=0.42",
      )
      .to(
        root.querySelector(".site-intro__copy"),
        {
          y: -34,
          opacity: 0,
          duration: 0.46,
        },
        "-=0.24",
      )
      .to(
        root.querySelector(".site-intro__wash"),
        {
          clipPath: "ellipse(0% 0% at 86% 8%)",
          duration: 0.62,
          ease: "power3.inOut",
        },
        "-=0.28",
      )
      .to(root, { autoAlpha: 0, duration: 0.24 }, "-=0.12");

    const startTimer = window.setTimeout(() => timeline.play(0), 80);

    return () => {
      window.clearTimeout(startTimer);
      timeline.kill();
    };
  }, [prefersReducedMotion, visible]);

  if (!visible) return null;
  return (
    <div ref={rootRef} className="site-intro" aria-hidden="true">
      <div className="site-intro__wash">
        <div className="site-intro__staff">
          {Array.from({ length: 5 }, (_, index) => (
            <i key={index} className="site-intro__staff-line" />
          ))}
        </div>
        <div className="site-intro__notes">
          {["♪", "♩", "♫", "♬", "♩"].map((note, index) => (
            <span
              key={`${note}-${index}`}
              className="site-intro__note"
              data-note={index}
            >
              {note}
            </span>
          ))}
        </div>
      </div>
      <div className="site-intro__type site-intro__copy">
        <small className="site-intro__eyebrow">01 · Language in motion</small>
        <span className="site-intro__word">INKFLOW</span>
        <em className="site-intro__tagline">where language finds its rhythm</em>
      </div>
    </div>
  );
}
