function isActive(pathname: string, search: string, path: string) {
  if (path.includes("?")) {
    const [targetPath, targetSearch] = path.split("?");
    return pathname === targetPath && search === `?${targetSearch}`;
  }
  if (path === "/") {
    return (pathname === "/" || pathname === "/study") && search === "";
  }
  if (path === "/library") {
    return pathname === "/library" || pathname.startsWith("/book/");
  }
  return pathname === path || pathname.startsWith(`${path}/`);
}

export function PersistentDock() {
  const location = useLocation();
  const navigate = useNavigate();
  const [menuSignal, setMenuSignal] = useState(0);
  const [dismissed, setDismissed] = useState(false);
  const isHome = location.pathname === "/";

  useEffect(() => {
    const openMenu = () => {
      setDismissed(false);
      setMenuSignal((current) => current + 1);
    };
    window.addEventListener("inkflow:open-menu", openMenu);
    return () => window.removeEventListener("inkflow:open-menu", openMenu);
  }, []);

  const menuItems = useMemo(
    () =>
      directory.map((item) => ({
        label: item.label,
        ariaLabel: item.ariaLabel,
        link: "#",
        children: item.children.map((child) => ({
          label: child.label,
          ariaLabel: child.ariaLabel,
          link: child.path,
          disabled: "disabled" in child ? child.disabled : undefined,
          className: isActive(location.pathname, location.search, child.path)
            ? "is-active"
            : undefined,
        })),
      })),
    [location.pathname, location.search],
  );

  return (
    <StaggeredMenu
      className="inkflow-staggered-menu"
      isFixed
      position="right"
      items={menuItems}
      colors={["#b0b1cf", "#d7d4e6", "#f1e2d2"]}
      accentColor="#65647f"
      displaySocials={false}
      displayItemNumbering={false}
      menuButtonColor="#f8f0e8"
      openMenuButtonColor="#fffaf3"
      logoUrl="/inkflow-logo.png"
      hideToggle={isHome}
      openSignal={menuSignal}
      dismissed={dismissed}
      onItemClick={(item) => {
        const targetPath = item.link;
        if (!targetPath.startsWith("/")) return;
        setDismissed(true);
        if (
          targetPath.startsWith("/?drawer=") ||
          targetPath.startsWith("/?book=")
        ) {
          window.dispatchEvent(
            new CustomEvent("inkflow:shelf-action", {
              detail: { path: targetPath, at: Date.now() },
            }),
          );
        }
        navigate(targetPath);
      }}
    />
  );
}
