function createArchiveBook(
  row: ShelfRow,
  rowIndex: number,
  volumeIndex: number,
  color: string,
  thickness: number,
  height: number,
): ReaderBook {
  const archive =
    SHELF_ARCHIVE_BOOKS[
      (rowIndex * 5 + volumeIndex) % SHELF_ARCHIVE_BOOKS.length
    ] ?? SHELF_ARCHIVE_BOOKS[0];
  const slug = archive.title.toLowerCase().replace(/[^a-z]+/g, "-");

  return {
    id: `shelf-${row.number}-${slug}-${volumeIndex}` as ReaderBook["id"],
    title: archive.title,
    zhTitle: archive.zhTitle,
    author: "InkFlow Archive",
    spine: color,
    pageTint: "#FBF6EF",
    slot: [0, rowIndex],
    coverWidth: 0.18,
    height,
    thickness,
    lean: ((volumeIndex % 5) - 2) * 0.006,
    editable: false,
    source: "",
    translation: "",
  };
}

export function createShelfVolumes(
  row: ShelfRow,
  rowIndex: number,
): ShelfVolume[] {
  const coreRow = row.books.length === 3;
  const volumes: ShelfVolume[] = [];
  let cursor = coreRow ? -0.72 : -1.48;
  let archiveIndex = 0;

  const addArchiveVolume = (x: number, thickness: number, height: number) => {
    const color =
      FILLER_PALETTE[
        (archiveIndex + rowIndex * 2) % FILLER_PALETTE.length
      ] ?? COLORS.riceFrost;
    volumes.push({
      book: createArchiveBook(
        row,
        rowIndex,
        archiveIndex,
        color,
        thickness,
        height,
      ),
      x,
      thickness,
      height,
      depth: 0.37 + ((archiveIndex + rowIndex) % 3) * 0.018,
      z: 0.055 + (archiveIndex % 2) * 0.024,
      lean: (((archiveIndex + rowIndex) % 5) - 2) * 0.006,
      core: false,
    });
    archiveIndex += 1;
  };

  if (coreRow) {
    let leftCursor = -1.52;
    while (leftCursor < cursor - 0.1 && archiveIndex < 4) {
      const thickness = 0.12 + ((archiveIndex + rowIndex) % 3) * 0.045;
      const height = 0.55 + ((archiveIndex * 2 + rowIndex) % 4) * 0.07;
      addArchiveVolume(leftCursor + thickness / 2, thickness, height);
      leftCursor += thickness + 0.045;
    }
  }

  row.books.forEach((book, index) => {
    const coreBook = book.id.startsWith("core-");
    const thickness = coreBook
      ? 0.18
      : 0.13 + ((index + rowIndex) % 4) * 0.024;
    const height = coreBook
      ? 0.68
      : 0.52 + ((index * 3 + rowIndex) % 5) * 0.055;
    const x = cursor + thickness / 2;
    cursor += thickness + 0.055;
    volumes.push({
      book,
      x,
      thickness,
      height,
      depth: 0.42,
      z: 0.12 + (index % 2) * 0.022,
      lean: book.lean,
      core: coreBook,
    });
  });

  while (cursor < 0.72 && archiveIndex < 9) {
    const thickness = 0.12 + ((archiveIndex + rowIndex) % 3) * 0.045;
    const height = 0.55 + ((archiveIndex * 2 + rowIndex) % 4) * 0.07;
    addArchiveVolume(cursor + thickness / 2, thickness, height);
    cursor += thickness + 0.045;
  }

  return volumes.sort((a, b) => a.x - b.x);
}

