export function WoodenBookshelf({
  actionKey = "",
  initialDrawer = null,
  initialBookId = null,
}: {
  actionKey?: string;
  initialDrawer?: ShelfDrawerId | null;
  initialBookId?: string | null;
}) {
  const reducedMotion = useReducedMotion();
  const [hoveredBookId, setHoveredBookId] = useState<string | null>(null);
  const [selectedBookId, setSelectedBookId] = useState<string | null>(null);
  const [hoveredPianoKeyIndex, setHoveredPianoKeyIndex] = useState<
    number | null
  >(null);
  const [pressedPianoKeyIndex, setPressedPianoKeyIndex] = useState<
    number | null
  >(null);
  const [selectedPianoRegion, setSelectedPianoRegion] = useState<number | null>(
    null,
  );
  const [activeDrawerId, setActiveDrawerId] = useState<DrawerId | null>(null);
  const [zoomedBook, setZoomedBook] = useState<ReaderBook | null>(null);
  const [openedCoreBook, setOpenedCoreBook] = useState<ReaderBook | null>(null);
  const [wordsOpen, setWordsOpen] = useState(false);
  const [openingBook, setOpeningBook] = useState<ReaderBook | null>(null);
  const [collectedWords, setCollectedWords] =
    useState<CollectedWord[]>(loadCollectedWords);
  const [shelfView, setShelfView] = useState<ShelfView>("overview");
  const [bookReturnView, setBookReturnView] =
    useState<BookReturnView>("focused");
  const [shelfHighlighted, setShelfHighlighted] = useState(false);
  const [shelfHovered, setShelfHovered] = useState(false);
  const [discardTarget, setDiscardTarget] = useState<DiscardTarget | null>(null);
  const [discardedDrawerItems, setDiscardedDrawerItems] = useState<Set<string>>(
    () => new Set(),
  );
  const [focusEpoch, setFocusEpoch] = useState(0);
  const playPianoNote = usePianoSynth();
  const openTimer = useRef<number | null>(null);
  const focusTimer = useRef<number | null>(null);
  const returnTimer = useRef<number | null>(null);
  const highlightTimer = useRef<number | null>(null);
  const pendingOpenBook = useRef<ReaderBook | null>(null);
  const requestedDrawer = useRef<string | null>(null);
  const requestedBookId = useRef<string | null>(null);
  const shelfPointer = useRef<ShelfPointerState>({
    x: 0,
    y: 0,
    active: false,
  });
  const cameraZoomRef = useRef(DEFAULT_FOCUS_ZOOM);
  const cameraPanRef = useRef(0);
  const cameraDragRef = useRef({
    active: false,
    moved: false,
    startY: 0,
    startPan: 0,
  });
  const shelfViewRef = useRef<ShelfView>("overview");
  const rows = useMemo<Array<ShelfRow>>(
    () =>
      SHELF_LEVELS.map((level, index) => ({
        ...level,
        books: index === 2 ? CORE_BOOKS : [],
      })),
    [],
  );
  const shelfBooks = useMemo(
    () =>
      rows.flatMap((row, rowIndex) =>
        createShelfVolumes(row, rowIndex)
          .filter((volume) => volume.core)
          .map((volume) => volume.book),
      ),
    [rows],
  );
  const hoveredBook =
    shelfBooks.find((book) => book.id === hoveredBookId) ?? null;
  const hoveredPianoRegion =
    hoveredPianoKeyIndex === null
      ? null
      : practiceRegionForKey(hoveredPianoKeyIndex);
  const activePianoNote =
    hoveredPianoRegion === null && selectedPianoRegion === null
      ? null
      : PIANO_NOTES[hoveredPianoRegion ?? selectedPianoRegion ?? 0];

  useEffect(
    () => () => {
      if (openTimer.current !== null) window.clearTimeout(openTimer.current);
      if (focusTimer.current !== null) window.clearTimeout(focusTimer.current);
      if (returnTimer.current !== null) window.clearTimeout(returnTimer.current);
      if (highlightTimer.current !== null) {
        window.clearTimeout(highlightTimer.current);
      }
      document.body.style.cursor = "";
    },
    [],
  );
  useEffect(() => {
    shelfViewRef.current = shelfView;
  }, [shelfView]);

  const openFocusedBook = useCallback(
    (book: ReaderBook) => {
      if (openTimer.current !== null) return;

      if (reducedMotion) {
        setZoomedBook(null);
        setOpenedCoreBook(book);
        return;
      }

      setZoomedBook(null);
      setSelectedBookId(book.id);
      setZoomedBook(null);
      setOpeningBook(book);
      openTimer.current = window.setTimeout(() => {
        openTimer.current = null;
        setOpeningBook(null);
        setOpenedCoreBook(book);
      }, OPEN_TRANSITION_MS);
    },
    [reducedMotion],
  );

  const focusShelf = useCallback(() => {
    if (shelfView !== "overview") return;

    setHoveredBookId(null);
    setSelectedBookId(null);
    setZoomedBook(null);
    setOpeningBook(null);
    setActiveDrawerId(null);
    setShelfHovered(false);
    setShelfHighlighted(true);
    setFocusEpoch((value) => value + 1);
    setShelfView("entering");

    if (highlightTimer.current !== null) {
      window.clearTimeout(highlightTimer.current);
    }
    highlightTimer.current = window.setTimeout(() => {
      highlightTimer.current = null;
      setShelfHighlighted(false);
    }, reducedMotion ? 120 : 620);

    if (focusTimer.current !== null) {
      window.clearTimeout(focusTimer.current);
    }
    if (reducedMotion) {
      window.requestAnimationFrame(() => {
        setShelfView("focused");
        const pending = pendingOpenBook.current;
        pendingOpenBook.current = null;
        if (pending) {
          setSelectedBookId(pending.id);
          openFocusedBook(pending);
        }
      });
    } else {
      focusTimer.current = window.setTimeout(() => {
        focusTimer.current = null;
        setShelfView("focused");
        const pending = pendingOpenBook.current;
        pendingOpenBook.current = null;
        if (pending) {
          setSelectedBookId(pending.id);
          openFocusedBook(pending);
        }
      }, FOCUS_TRANSITION_MS);
    }
  }, [openFocusedBook, reducedMotion, shelfView]);

  const returnToOverview = useCallback(() => {
    if (shelfView === "overview" || shelfView === "returning") return;

    if (openTimer.current !== null) {
      window.clearTimeout(openTimer.current);
      openTimer.current = null;
    }
    setHoveredBookId(null);
    setSelectedBookId(null);
    setZoomedBook(null);
    setOpenedCoreBook(null);
    setOpeningBook(null);
    setWordsOpen(false);
    setActiveDrawerId(null);
    pendingOpenBook.current = null;
    cameraZoomRef.current = DEFAULT_FOCUS_ZOOM;
    cameraPanRef.current = 0;
    setBookReturnView("focused");
    setShelfHighlighted(false);
    setShelfView("returning");

    if (returnTimer.current !== null) {
      window.clearTimeout(returnTimer.current);
    }
    if (reducedMotion) {
      window.requestAnimationFrame(() => setShelfView("overview"));
    } else {
      returnTimer.current = window.setTimeout(() => {
        returnTimer.current = null;
        setShelfView("overview");
      }, RETURN_TRANSITION_MS);
    }
  }, [reducedMotion, shelfView]);

  const closeBookExperience = useCallback(() => {
    if (openTimer.current !== null) {
      window.clearTimeout(openTimer.current);
      openTimer.current = null;
    }

    setOpeningBook(null);
    setZoomedBook(null);
    setOpenedCoreBook(null);
    setWordsOpen(false);

    if (bookReturnView === "overview") {
      returnToOverview();
    }
  }, [bookReturnView, returnToOverview]);

  useEffect(() => {
    if (!initialDrawer) {
      requestedDrawer.current = null;
      return;
    }
    const requestKey = `${actionKey}:${initialDrawer}`;
    if (requestedDrawer.current === requestKey) return;
    if (shelfView === "overview") {
      focusShelf();
      return;
    }
    if (shelfView === "focused") {
      requestedDrawer.current = requestKey;
      setActiveDrawerId(initialDrawer);
    }
  }, [actionKey, focusShelf, initialDrawer, shelfView]);

  useEffect(() => {
    if (!initialBookId) {
      requestedBookId.current = null;
      return;
    }
    const requestKey = `${actionKey}:${initialBookId}`;
    if (requestedBookId.current === requestKey) return;
    const target = CORE_BOOKS.find((book) => book.id === initialBookId);
    if (!target) return;
    if (shelfView === "overview") {
      setBookReturnView("overview");
      focusShelf();
      return;
    }
    if (shelfView === "focused") {
      requestedBookId.current = requestKey;
      setBookReturnView("focused");
      openFocusedBook(target);
    }
  }, [actionKey, focusShelf, initialBookId, openFocusedBook, shelfView]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key !== "Escape" || shelfView === "overview") return;
      const target = event.target;
      if (
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        (target instanceof HTMLElement && target.isContentEditable)
      ) {
        return;
      }
      event.preventDefault();
      if (zoomedBook || openedCoreBook || openingBook) {
        closeBookExperience();
      } else {
        returnToOverview();
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [
    closeBookExperience,
    openedCoreBook,
    openingBook,
    returnToOverview,
    shelfView,
    zoomedBook,
  ]);

  const openBook = useCallback((book: ReaderBook) => {
    if (shelfView !== "focused") {
      setBookReturnView("overview");
      pendingOpenBook.current = book;
      focusShelf();
      return;
    }
    setBookReturnView("focused");
    setWordsOpen(false);
    openFocusedBook(book);
  }, [focusShelf, openFocusedBook, shelfView]);
  const handleBookHover = useCallback((book: ReaderBook | null) => {
    setHoveredBookId(book?.id ?? null);
  }, []);

  const handlePianoKeyPlay = useCallback((index: number) => {
    playPianoNote(index);
  }, [playPianoNote]);
  const handlePianoKeyHover = useCallback((index: number | null) => {
    setHoveredPianoKeyIndex(index);
    if (index === null) setPressedPianoKeyIndex(null);
  }, []);
  const handlePianoKeyPress = useCallback((index: number) => {
    setPressedPianoKeyIndex(index);
  }, []);
  const handlePianoKeyRelease = useCallback(() => {
    setPressedPianoKeyIndex(null);
  }, []);
  const handlePianoKeySelect = useCallback((index: number) => {
    const region = practiceRegionForKey(index);
    if (region === 1) {
      setSelectedPianoRegion(1);
      setWordsOpen(true);
      setActiveDrawerId(null);
      setOpenedCoreBook(null);
      playPianoNote(index, true);
      return;
    }
    setWordsOpen(false);
    setSelectedPianoRegion((current) => (current === region ? null : region));
    playPianoNote(index, true);
  }, [playPianoNote]);

  const collectWord = (item: CollectedWord) => {
    setCollectedWords((current) => {
      const next = current.some((entry) => entry.id === item.id)
        ? current
        : [item, ...current];
      if (typeof localStorage !== "undefined") {
        localStorage.setItem(COLLECTION_STORAGE_KEY, JSON.stringify(next));
      }
      return next;
    });
  };

  const confirmDiscard = () => {
    if (!discardTarget) return;
    const { drawerId, item } = discardTarget;
    const key = drawerItemKey(drawerId, item);
    setDiscardedDrawerItems((current) => {
      const next = new Set(current);
      next.add(key);
      return next;
    });
    if (drawerId === "collection") {
      setCollectedWords((current) =>
        current.filter((entry) => entry.title !== item.title),
      );
    }
    setDiscardTarget(null);
  };

  return (
    <div
      className={cn(
        "study-shelf",
        `is-${shelfView}`,
        shelfHighlighted && "is-highlighting",
        shelfHovered && "is-hovering",
        zoomedBook && "has-zoom-page",
        openedCoreBook && "has-learning-page",
        openingBook && "is-opening-book",
        wordsOpen && "has-words-page",
      )}
      data-shelf-view={shelfView}
      aria-busy={shelfView === "entering" || shelfView === "returning"}
      onPointerEnter={(event) => {
        if (event.pointerType === "touch") return;
        shelfPointer.current.active = true;
        setShelfHovered(true);
      }}
      onPointerMoveCapture={(event) => {
        if (event.pointerType === "touch") return;
        const rect = event.currentTarget.getBoundingClientRect();
        shelfPointer.current.x = Math.max(
          -1,
          Math.min(1, ((event.clientX - rect.left) / rect.width) * 2 - 1),
        );
        shelfPointer.current.y = Math.max(
          -1,
          Math.min(1, ((event.clientY - rect.top) / rect.height) * 2 - 1),
        );
        shelfPointer.current.active = true;
        const drag = cameraDragRef.current;
        if (drag.active) {
          const delta = event.clientY - drag.startY;
          if (Math.abs(delta) > 3) drag.moved = true;
          cameraPanRef.current = THREE.MathUtils.clamp(
            drag.startPan - delta * 0.0025,
            -0.68,
            0.68,
          );
        }
      }}
      onPointerDownCapture={(event) => {
        if (
          shelfView !== "focused" ||
          event.pointerType !== "mouse" ||
          event.button !== 0 ||
          !(event.target instanceof HTMLCanvasElement)
        ) {
          return;
        }
        event.currentTarget.setPointerCapture(event.pointerId);
        cameraDragRef.current = {
          active: true,
          moved: false,
          startY: event.clientY,
          startPan: cameraPanRef.current,
        };
      }}
      onPointerUpCapture={(event) => {
        const drag = cameraDragRef.current;
        if (!drag.active) return;
        drag.active = false;
        if (event.currentTarget.hasPointerCapture(event.pointerId)) {
          event.currentTarget.releasePointerCapture(event.pointerId);
        }
      }}
      onPointerCancelCapture={() => {
        cameraDragRef.current.active = false;
      }}
      onClickCapture={(event) => {
        if (!cameraDragRef.current.moved) return;
        event.preventDefault();
        event.stopPropagation();
        cameraDragRef.current.moved = false;
      }}
      onPointerLeave={() => {
        shelfPointer.current.active = false;
        shelfPointer.current.x = 0;
        shelfPointer.current.y = 0;
        setShelfHovered(false);
        setHoveredBookId(null);
        setHoveredPianoKeyIndex(null);
        setPressedPianoKeyIndex(null);
        cameraDragRef.current.active = false;
      }}
    >
      <div className="study-shelf__ambient" aria-hidden="true" />
      <SparkleField />
      <div className="study-shelf__speed-lines" aria-hidden="true" />

      <div
        className="study-shelf__canvas"
        onWheelCapture={(event) => {
          if (
            shelfView !== "focused" ||
            zoomedBook ||
            openedCoreBook ||
            wordsOpen ||
            activeDrawerId
          ) {
            return;
          }
          event.preventDefault();
          cameraZoomRef.current = THREE.MathUtils.clamp(
            cameraZoomRef.current - event.deltaY * 0.001,
            1,
            MAX_FOCUS_ZOOM,
          );
        }}
        onDoubleClick={() => {
          if (shelfView === "focused") {
            cameraZoomRef.current = DEFAULT_FOCUS_ZOOM;
            cameraPanRef.current = 0;
          }
        }}
      >
        <Canvas
          frameloop="always"
          shadows="soft"
          dpr={[1, 1.5]}
          camera={{ position: [5.4, 2.15, 12.6], fov: 24, near: 0.1, far: 60 }}
          gl={{
            antialias: true,
            alpha: true,
            powerPreference: "high-performance",
          }}
          onCreated={({ gl }) => {
            gl.outputColorSpace = THREE.SRGBColorSpace;
            gl.toneMapping = THREE.ACESFilmicToneMapping;
            gl.toneMappingExposure = 0.96;
          }}
        >
          <SceneCamera
            reducedMotion={Boolean(reducedMotion)}
            zoomRef={cameraZoomRef}
            panRef={cameraPanRef}
            viewRef={shelfViewRef}
          />
          <BookshelfScene
            rows={rows}
            shelfView={shelfView}
            shelfPointer={shelfPointer}
            focusEpoch={focusEpoch}
            shelfHighlighted={shelfHighlighted}
            hoveredBookId={hoveredBookId}
            selectedBookId={selectedBookId}
            hoveredPianoKeyIndex={hoveredPianoKeyIndex}
            pressedPianoKeyIndex={pressedPianoKeyIndex}
            selectedPianoRegion={selectedPianoRegion}
            activeDrawerId={activeDrawerId}
            discardedDrawerItems={discardedDrawerItems}
            onHover={handleBookHover}
            onOpen={openBook}
            onKeyHover={handlePianoKeyHover}
            onKeyPlay={handlePianoKeyPlay}
            onKeyPress={handlePianoKeyPress}
            onKeyRelease={handlePianoKeyRelease}
            onKeySelect={handlePianoKeySelect}
            onShelfFocus={focusShelf}
            onDrawerToggle={(drawerId) =>
              setActiveDrawerId((current) =>
                current === drawerId ? null : drawerId,
              )
            }
          />
        </Canvas>
      </div>

      <BookOpeningSequence book={openingBook} />

      <BookInfoCard
        book={hoveredBook}
        onContinue={openBook}
      />
      <CoreLearningPanel
        book={openedCoreBook}
        savedIds={collectedWords.map((item) => item.id)}
        onSave={collectWord}
        onClose={closeBookExperience}
      />
      <BookZoomPanel
        book={zoomedBook}
        returnLabel={
          bookReturnView === "overview" ? "返回全景" : "返回书架"
        }
        onClose={closeBookExperience}
        onOpen={openFocusedBook}
      />
      <WordsExplorer
        open={wordsOpen}
        collectedIds={collectedWords.map((item) => item.id)}
        onClose={() => setWordsOpen(false)}
        onCollect={collectWord}
      />
      <DrawerPanel
        drawerId={activeDrawerId}
        collectionItems={collectedWords}
        discardedDrawerItems={discardedDrawerItems}
        onDiscard={(drawerId, item) =>
          setDiscardTarget({ drawerId, item })
        }
        onClose={() => setActiveDrawerId(null)}
      />
      <DiscardPaper
        target={discardTarget}
        onCancel={() => setDiscardTarget(null)}
        onConfirm={confirmDiscard}
      />

      <AnimatePresence>
        {shelfView !== "overview" ? (
          <motion.button
            type="button"
            className="study-shelf__back"
            initial={{ opacity: 0, x: -12 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -8 }}
            transition={{ duration: 0.22, ease: [0.22, 1, 0.36, 1] }}
            onClick={returnToOverview}
          >
            <ArrowLeft size={16} />
            <span>返回全景</span>
          </motion.button>
        ) : null}
      </AnimatePresence>

      {activePianoNote ? (
        <motion.div
          className={cn(
            "study-shelf__key-callout",
            "study-shelf__key-callout--note",
            selectedPianoRegion !== null &&
              hoveredPianoKeyIndex === null &&
              "is-pinned",
          )}
          initial={false}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.18, ease: [0.22, 1, 0.36, 1] }}
        >
          <span className="study-shelf__note-pulse" aria-hidden="true">
            ♪
          </span>
          <span>
            <strong>{activePianoNote.skill}</strong>
            <small>{activePianoNote.detail}</small>
            <em>
              {selectedPianoRegion !== null &&
              hoveredPianoKeyIndex === null
                ? "Practice selected"
                : "Click to focus"}
            </em>
          </span>
        </motion.div>
      ) : null}

      <div className="study-shelf__a11y" aria-label="书架中的书籍">
        <button
          type="button"
          className="study-shelf__focus-access"
          onClick={focusShelf}
        >
          进入书架近景
        </button>
        {shelfBooks.map((book) => (
          <button
            type="button"
            className="study-book"
            key={book.id}
            onClick={() => openBook(book)}
            onFocus={() => setHoveredBookId(book.id)}
            onBlur={() => setHoveredBookId(null)}
          >
            打开 {book.title}，{book.zhTitle}
          </button>
        ))}
        {PIANO_NOTES.map((note, region) => (
          <button
            type="button"
            className="study-piano-access"
            key={note.label}
            onClick={() =>
              handlePianoKeySelect(firstKeyForPracticeRegion(region))
            }
          >
            打开 {note.skill}，{note.detail}
          </button>
        ))}
      </div>
    </div>
  );
}

interface CameraPose {
  position: [number, number, number];
  target: [number, number, number];
  fov: number;
}

function overviewCameraPose(width: number): CameraPose {
  const compact = width < 720;
  return {
    position: compact
      ? [4.75, 2.05, 13.4]
      : [5.4, 2.15, 12.6],
    target: [0, -0.02, 0],
    fov: 24,
  };
}

function focusedCameraPose(
  width: number,
  zoom = 1,
  panY = 0,
): CameraPose {
  const compact = width < 720;
  const pan = panY * (compact ? 0.42 : 0.56);
  return {
    position: compact
      ? [0, 0.2 + pan, 9.5 / zoom]
      : [0, 0.14 + pan, 7.5 / zoom],
    target: [0, pan, 0],
    fov: compact ? 44 : 41,
  };
}

function easeOutCubic(value: number) {
  return 1 - Math.pow(1 - value, 3);
}

function SceneCamera({
  reducedMotion,
  zoomRef,
  panRef,
  viewRef,
}: {
  reducedMotion: boolean;
  zoomRef: { current: number };
  panRef: { current: number };
  viewRef: { current: ShelfView };
}) {
  const { size } = useThree();
  const camera = useThree((state) => state.camera) as THREE.PerspectiveCamera;
  const initialized = useRef(false);
  const overviewFrameApplied = useRef(false);
  const path = useRef(viewRef.current === "returning" ? 1 : 0);
  const previousView = useRef(viewRef.current);
  const currentPosition = useRef(new THREE.Vector3());
  const currentTarget = useRef(new THREE.Vector3());
  const positionVelocity = useRef(new THREE.Vector3());
  const targetVelocity = useRef(new THREE.Vector3());
  const desiredPosition = useRef(new THREE.Vector3());
  const desiredTarget = useRef(new THREE.Vector3());

  useEffect(() => {
    if (initialized.current) return;
    const pose = overviewCameraPose(size.width);
    camera.position.fromArray(pose.position);
    camera.fov = pose.fov;
    camera.lookAt(...pose.target);
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
    currentPosition.current.copy(camera.position);
    currentTarget.current.fromArray(pose.target);
    overviewFrameApplied.current = false;
    initialized.current = true;
  }, [camera, size.width]);

  useFrame((_, delta) => {
    if (!initialized.current) return;
    const view = viewRef.current;
    if (view !== previousView.current) {
      if (view === "entering") path.current = 0;
      if (view === "returning") path.current = 1;
      previousView.current = view;
    }

    const dt = Math.min(delta, 1 / 30);
    const overview = overviewCameraPose(size.width);
    const focused = focusedCameraPose(
      size.width,
      zoomRef.current,
      view === "focused" ? panRef.current : 0,
    );
    const settledOverview =
      view === "overview" &&
      path.current === 0 &&
      positionVelocity.current.lengthSq() < 0.000001 &&
      targetVelocity.current.lengthSq() < 0.000001 &&
      Math.abs(camera.fov - overview.fov) < 0.01;
    const settledFocused =
      view === "focused" &&
      path.current === 1 &&
      positionVelocity.current.lengthSq() < 0.000001 &&
      targetVelocity.current.lengthSq() < 0.000001 &&
      Math.abs(camera.fov - focused.fov) < 0.01 &&
      Math.abs(currentPosition.current.x - focused.position[0]) < 0.002 &&
      Math.abs(currentPosition.current.y - focused.position[1]) < 0.002 &&
      Math.abs(currentPosition.current.z - focused.position[2]) < 0.002 &&
      Math.abs(currentTarget.current.y - focused.target[1]) < 0.002;
    if (
      (settledOverview && overviewFrameApplied.current) ||
      settledFocused
    ) {
      return;
    }

    if (view === "entering" || view === "focused") {
      path.current = Math.min(1, path.current + dt / (FOCUS_TRANSITION_MS / 1000));
    } else if (view === "returning") {
      path.current = Math.max(0, path.current - dt / (RETURN_TRANSITION_MS / 1000));
    } else {
      path.current = 0;
    }

    const blend = easeOutCubic(path.current);
    const start = view === "returning" ? focused : overview;
    const end = view === "returning" ? overview : focused;

    desiredPosition.current.fromArray(start.position).lerp(
      new THREE.Vector3().fromArray(end.position),
      blend,
    );
    desiredTarget.current.fromArray(start.target).lerp(
      new THREE.Vector3().fromArray(end.target),
      blend,
    );

    const orbit = Math.sin(Math.PI * path.current);
    const angle =
      THREE.MathUtils.degToRad(6) *
      orbit *
      (view === "returning" ? -1 : 1);
    const pivot = desiredTarget.current;
    const dx = desiredPosition.current.x - pivot.x;
    const dz = desiredPosition.current.z - pivot.z;
    desiredPosition.current.x =
      pivot.x + dx * Math.cos(angle) - dz * Math.sin(angle);
    desiredPosition.current.z =
      pivot.z + dx * Math.sin(angle) + dz * Math.cos(angle);
    desiredPosition.current.y += orbit * 0.2;

    const desiredFov = THREE.MathUtils.lerp(start.fov, end.fov, blend);

    if (reducedMotion) {
      currentPosition.current.copy(desiredPosition.current);
      currentTarget.current.copy(desiredTarget.current);
      camera.position.copy(currentPosition.current);
      camera.lookAt(currentTarget.current);
      camera.fov = desiredFov;
      camera.updateProjectionMatrix();
      return;
    }

    const settle = (
      current: THREE.Vector3,
      velocity: THREE.Vector3,
      target: THREE.Vector3,
    ) => {
      velocity.addScaledVector(
        new THREE.Vector3().subVectors(target, current),
        155 * dt,
      );
      velocity.multiplyScalar(Math.exp(-24.5 * dt));
      velocity.clampLength(0, 28);
      current.addScaledVector(velocity, dt);
    };

    settle(
      currentPosition.current,
      positionVelocity.current,
      desiredPosition.current,
    );
    settle(
      currentTarget.current,
      targetVelocity.current,
      desiredTarget.current,
    );

    camera.position.copy(currentPosition.current);
    camera.lookAt(currentTarget.current);
    camera.fov = THREE.MathUtils.damp(camera.fov, desiredFov, 13, dt);
    camera.updateProjectionMatrix();
    camera.updateMatrixWorld();
    if (view === "overview") overviewFrameApplied.current = true;
  });

  return null;
}

function BookshelfScene({
  rows,
  shelfView,
  shelfPointer,
  focusEpoch,
  shelfHighlighted,
  hoveredBookId,
  selectedBookId,
  hoveredPianoKeyIndex,
  pressedPianoKeyIndex,
  selectedPianoRegion,
  activeDrawerId,
  discardedDrawerItems,
  onHover,
  onOpen,
  onKeyHover,
  onKeyPlay,
  onKeyPress,
  onKeyRelease,
  onKeySelect,
  onShelfFocus,
  onDrawerToggle,
}: {
  rows: ShelfRow[];
  shelfView: ShelfView;
  shelfPointer: { current: ShelfPointerState };
  focusEpoch: number;
  shelfHighlighted: boolean;
  hoveredBookId: string | null;
  selectedBookId: string | null;
  hoveredPianoKeyIndex: number | null;
  pressedPianoKeyIndex: number | null;
  selectedPianoRegion: number | null;
  activeDrawerId: DrawerId | null;
  discardedDrawerItems: Set<string>;
  onHover: (book: ReaderBook | null) => void;
  onOpen: (book: ReaderBook) => void;
  onKeyHover: (index: number | null) => void;
  onKeyPlay: (index: number) => void;
  onKeyPress: (index: number) => void;
  onKeyRelease: () => void;
  onKeySelect: (index: number) => void;
  onShelfFocus: () => void;
  onDrawerToggle: (drawerId: DrawerId) => void;
}) {
  const shelfGroup = useRef<THREE.Group>(null);
  const bookHandles = useRef(new Map<string, BookVisualHandle>());
  const booksSettled = useRef(false);
  const [pinnedBookIds, setPinnedBookIds] = useState<Set<string>>(
    () => new Set(),
  );
  const { size } = useThree();
  const cabinetGeometry = useMemo(createCabinetGeometry, []);
  const cabinetMaterial = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: COLORS.cabinet,
        roughness: 0.66,
        metalness: 0.02,
      }),
    [],
  );
  const backingMaterial = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: "#DED8E4",
        roughness: 0.9,
      }),
    [],
  );
  const shelfMaterial = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: COLORS.shelf,
        roughness: 0.58,
        metalness: 0.01,
      }),
    [],
  );
  const focused = shelfView === "focused";
  const registerBook = useCallback(
    (id: string, handle: BookVisualHandle | null) => {
      if (handle) bookHandles.current.set(id, handle);
      else bookHandles.current.delete(id);
      booksSettled.current = false;
    },
    [],
  );
  const togglePinnedBook = useCallback((id: string) => {
    setPinnedBookIds((current) => {
      const next = new Set(current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
    booksSettled.current = false;
  }, []);

  useEffect(() => {
    booksSettled.current = false;
  }, [focused, hoveredBookId, pinnedBookIds, selectedBookId]);

  useFrame((_, delta) => {
    if (booksSettled.current) return;
    let allSettled = true;
    bookHandles.current.forEach((handle, id) => {
      const nextSettled = updateBookVisual(handle, delta, {
        hovered: hoveredBookId === id,
        selected: selectedBookId === id,
        pinned: pinnedBookIds.has(id),
        focused,
      });
      if (!nextSettled) allSettled = false;
    });
    booksSettled.current = allSettled;
  });

  useEffect(() => {
    const group = shelfGroup.current;
    if (!group) return;

    group.position.set(size.width < 720 ? 0.42 : 0, -0.08, 0);
    group.rotation.set(0, -0.055, 0);
    group.scale.setScalar(1);
  }, [size.width]);

  useFrame((_, delta) => {
    const group = shelfGroup.current;
    if (!group) return;

    const canFollow =
      (shelfView === "overview" || shelfView === "focused") &&
      shelfPointer.current.active;
    const amplitude = shelfView === "focused" ? 0.5 : 1;
    const x = canFollow ? shelfPointer.current.x * amplitude : 0;
    const y = canFollow ? shelfPointer.current.y * amplitude : 0;
    const baseX = size.width < 720 ? 0.42 : 0;
    const targetX = baseX + x * 0.06;
    const targetY = -0.08 - y * 0.032;
    const targetRotationX = y * 0.018;
    const targetRotationY = -0.055 - x * 0.026;
    const targetRotationZ = -x * 0.009;
    const atRest =
      Math.abs(group.position.x - targetX) < 0.0001 &&
      Math.abs(group.position.y - targetY) < 0.0001 &&
      Math.abs(group.rotation.x - targetRotationX) < 0.0001 &&
      Math.abs(group.rotation.y - targetRotationY) < 0.0001 &&
      Math.abs(group.rotation.z - targetRotationZ) < 0.0001;
    if (atRest) return;

    group.position.x = THREE.MathUtils.damp(group.position.x, targetX, 7, delta);
    group.position.y = THREE.MathUtils.damp(group.position.y, targetY, 7, delta);
    group.rotation.x = THREE.MathUtils.damp(
      group.rotation.x,
      targetRotationX,
      7,
      delta,
    );
    group.rotation.y = THREE.MathUtils.damp(
      group.rotation.y,
      targetRotationY,
      7,
      delta,
    );
    group.rotation.z = THREE.MathUtils.damp(
      group.rotation.z,
      targetRotationZ,
      7,
      delta,
    );
  });

  return (
    <>
      <ambientLight intensity={1.24} color="#F6F1FF" />
      <hemisphereLight
        args={["#FFFFFF", "#AEA8C4", 0.74]}
        position={[0, 7, 0]}
      />
      <directionalLight
        castShadow
        color="#FFF9F1"
        intensity={2.05}
        position={[6.5, 8, 10]}
        shadow-mapSize-width={1024}
        shadow-mapSize-height={1024}
        shadow-camera-left={-6}
        shadow-camera-right={6}
        shadow-camera-top={7}
        shadow-camera-bottom={-7}
        shadow-bias={-0.00015}
        shadow-normalBias={0.025}
        shadow-radius={4}
      />
      <directionalLight
        color="#C9C5F1"
        intensity={0.72}
        position={[-8, 3, 5]}
      />
      <pointLight
        color="#F8EADA"
        intensity={1.15}
        distance={12}
        position={[0.8, 1.8, 6.8]}
      />

      <group
        ref={shelfGroup}
        position={[0, -0.08, 0]}
        rotation={[0, -0.055, 0]}
        onClick={(event) => {
          if (shelfView !== "overview") return;
          event.stopPropagation();
          onShelfFocus();
        }}
      >
        <mesh
          geometry={cabinetGeometry}
          material={cabinetMaterial}
          castShadow
          receiveShadow
        />
        <InteriorBack material={backingMaterial} />
        <ShelfInterior material={shelfMaterial} />
        <KeyboardPanel
          hoveredKeyIndex={hoveredPianoKeyIndex}
          pressedKeyIndex={pressedPianoKeyIndex}
          selectedRegion={selectedPianoRegion}
          onKeyHover={onKeyHover}
          onKeyPlay={onKeyPlay}
          onKeyPress={onKeyPress}
          onKeyRelease={onKeyRelease}
          onKeySelect={onKeySelect}
        />
        <DrawerBank
          activeDrawerId={activeDrawerId}
          discardedDrawerItems={discardedDrawerItems}
          onToggle={onDrawerToggle}
        />
        <MusicStand />

        {rows.map((row, rowIndex) => (
          <ShelfRowBooks
            key={row.number}
            row={row}
            rowIndex={rowIndex}
            hoveredBookId={hoveredBookId}
            selectedBookId={selectedBookId}
            focused={shelfView === "focused"}
            focusEpoch={focusEpoch}
            pinnedBookIds={pinnedBookIds}
            registerBook={registerBook}
            onTogglePinned={togglePinnedBook}
            onHover={onHover}
            onOpen={onOpen}
          />
        ))}
      </group>
      <StickerWall active />
    </>
  );
}

function createCabinetGeometry() {
  const shape = new THREE.Shape();
  shape.moveTo(-1.64, 2.42);
  shape.bezierCurveTo(-2.16, 2.42, -2.58, 1.9, -2.62, 1.32);
  shape.lineTo(-2.62, -1.57);
  shape.bezierCurveTo(-2.62, -2.03, -2.28, -2.39, -1.82, -2.48);
  shape.lineTo(2.0, -2.48);
  shape.lineTo(2.0, 2.42);
  shape.closePath();

  const opening = new THREE.Path();
  opening.moveTo(-1.66, 2.18);
  opening.lineTo(1.08, 2.18);
  opening.lineTo(1.08, -2.25);
  opening.lineTo(-1.66, -2.25);
  opening.closePath();
  shape.holes.push(opening);

  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: 0.66,
    bevelEnabled: true,
    bevelThickness: 0.055,
    bevelSize: 0.055,
    bevelSegments: 4,
    curveSegments: 36,
  });
  geometry.translate(0, 0, -0.33);
  geometry.computeVertexNormals();
  return geometry;
}

