function KeyboardPanel({
  hoveredKeyIndex,
  pressedKeyIndex,
  selectedRegion,
  onKeyHover,
  onKeyPlay,
  onKeyPress,
  onKeyRelease,
  onKeySelect,
}: {
  hoveredKeyIndex: number | null;
  pressedKeyIndex: number | null;
  selectedRegion: number | null;
  onKeyHover: (index: number | null) => void;
  onKeyPlay: (index: number) => void;
  onKeyPress: (index: number) => void;
  onKeyRelease: () => void;
  onKeySelect: (index: number) => void;
}) {
  const keys = useMemo(
    () =>
      Array.from({ length: 43 }, (_, index) => {
        const position = index % 7;
        return {
          y: 2.03 - index * 0.0965,
          black:
            position === 1 ||
            position === 2 ||
            position === 4 ||
            position === 5 ||
            position === 6,
          wide: position === 0 || position === 3,
          region: practiceRegionForKey(index),
        };
      }),
    [],
  );
  const handles = useRef(new Map<number, KeyboardKeyVisualHandle>());
  const settled = useRef(false);
  const registerHandle = useCallback(
    (index: number, handle: KeyboardKeyVisualHandle | null) => {
      if (handle) handles.current.set(index, handle);
      else handles.current.delete(index);
      settled.current = false;
    },
    [],
  );

  useEffect(() => {
    settled.current = false;
  }, [hoveredKeyIndex, pressedKeyIndex, selectedRegion]);

  useFrame((_, delta) => {
    if (settled.current) return;
    let allSettled = true;
    handles.current.forEach((handle) => {
      const nextSettled = updateKeyboardKeyVisual(handle, delta, {
        hovered: hoveredKeyIndex === handle.index,
        pressed: pressedKeyIndex === handle.index,
        selected:
          selectedRegion !== null &&
          practiceRegionForKey(handle.index) === selectedRegion,
      });
      if (!nextSettled) allSettled = false;
    });
    settled.current = allSettled;
  });

  return (
    <group position={[1.52, 0.02, 0.39]}>
      <mesh position={[0, 0, -0.015]} castShadow receiveShadow>
        <boxGeometry args={[0.82, 4.64, 0.18]} />
        <meshStandardMaterial
          color="#AAA6C1"
          roughness={0.72}
          metalness={0.02}
        />
      </mesh>
      <mesh position={[0, 0, 0.055]} castShadow receiveShadow>
        <boxGeometry args={[0.7, 4.52, 0.075]} />
        <meshStandardMaterial
          color={COLORS.keyCream}
          roughness={0.54}
          metalness={0.01}
        />
      </mesh>
      {keys.map((key, index) => (
        <KeyboardPracticeKey
          key={index}
          index={index}
          y={key.y}
          black={key.black}
          wide={key.wide}
          region={key.region}
          hovered={hoveredKeyIndex === index}
          pressed={pressedKeyIndex === index}
          selected={selectedRegion === key.region}
          onHover={onKeyHover}
          onPlay={onKeyPlay}
          onPress={onKeyPress}
          onRelease={onKeyRelease}
          onSelect={onKeySelect}
          registerHandle={registerHandle}
        />
      ))}
    </group>
  );
}

