const KeyboardPracticeKey = memo(KeyboardPracticeKeyComponent);

function updateKeyboardKeyVisual(
  handle: KeyboardKeyVisualHandle,
  delta: number,
  state: { hovered: boolean; pressed: boolean; selected: boolean },
) {
  const group = handle.group;
  if (!group) return true;

  const effect = state.pressed || state.hovered ? 1 : state.selected ? 0.82 : 0;
  const targetX = effect * 0.06;
  const targetZ = state.pressed
    ? -0.17
    : state.hovered
      ? -0.115
      : -effect * 0.09;
  const targetScaleX = 1 + effect * 0.025;
  const targetScaleY = 1 + effect * 0.13;
  const targetScaleZ = 1 + effect * 0.18;
  const targetWhiteZ = effect * 0.055;
  const targetWhiteScaleZ = 1 + effect * 0.42;
  const targetCapZ = 0.038 + effect * 0.06;
  const targetCapScaleZ = 1 + effect * 0.5;
  const targetShadowZ = -0.045 - effect * 0.055;
  const targetShadowOpacity = 0.08 + effect * 0.34;
  const targetLight = state.pressed ? 0.42 : state.selected ? 0.32 : effect * 0.34;
  const targetBlack = state.pressed ? 0.46 : state.selected ? 0.36 : effect * 0.38;
  const targetMarker = 0.46 + effect * 0.5;
  const atRest =
    Math.abs(group.position.x - targetX) < 0.0005 &&
    Math.abs(group.position.z - targetZ) < 0.0005 &&
    Math.abs(group.scale.x - targetScaleX) < 0.0005 &&
    Math.abs(group.scale.y - targetScaleY) < 0.0005 &&
    Math.abs(group.scale.z - targetScaleZ) < 0.0005 &&
    Math.abs(
      (handle.whiteSurface?.position.z ?? 0) - targetWhiteZ,
    ) < 0.0005 &&
    Math.abs(
      (handle.whiteSurface?.scale.z ?? 1) - targetWhiteScaleZ,
    ) < 0.0005 &&
    Math.abs((handle.whiteCap?.position.z ?? 0) - targetCapZ) < 0.0005 &&
    Math.abs((handle.whiteCap?.scale.z ?? 1) - targetCapScaleZ) < 0.0005 &&
    Math.abs(
      (handle.shadowBase?.position.z ?? 0) - targetShadowZ,
    ) < 0.0005 &&
    Math.abs(
      (handle.shadowMaterial?.opacity ?? 0) - targetShadowOpacity,
    ) < 0.002 &&
    Math.abs(
      (handle.lightMaterial?.emissiveIntensity ?? 0) - targetLight,
    ) < 0.002 &&
    Math.abs(
      (handle.blackMaterial?.emissiveIntensity ?? 0) - targetBlack,
    ) < 0.002 &&
    Math.abs((handle.markerMaterial?.opacity ?? 0) - targetMarker) < 0.002;
  if (atRest) return true;

  group.position.x = THREE.MathUtils.damp(
    group.position.x,
    targetX,
    10,
    delta,
  );
  group.position.z = THREE.MathUtils.damp(
    group.position.z,
    targetZ,
    11,
    delta,
  );
  group.scale.x = THREE.MathUtils.damp(group.scale.x, targetScaleX, 10, delta);
  group.scale.y = THREE.MathUtils.damp(group.scale.y, targetScaleY, 10, delta);
  group.scale.z = THREE.MathUtils.damp(group.scale.z, targetScaleZ, 10, delta);
  if (handle.whiteSurface) {
    handle.whiteSurface.position.z = THREE.MathUtils.damp(
      handle.whiteSurface.position.z,
      targetWhiteZ,
      11,
      delta,
    );
    handle.whiteSurface.scale.z = THREE.MathUtils.damp(
      handle.whiteSurface.scale.z,
      targetWhiteScaleZ,
      10,
      delta,
    );
  }
  if (handle.whiteCap) {
    handle.whiteCap.position.z = THREE.MathUtils.damp(
      handle.whiteCap.position.z,
      targetCapZ,
      11,
      delta,
    );
    handle.whiteCap.scale.z = THREE.MathUtils.damp(
      handle.whiteCap.scale.z,
      targetCapScaleZ,
      10,
      delta,
    );
  }
  if (handle.shadowBase) {
    handle.shadowBase.position.z = THREE.MathUtils.damp(
      handle.shadowBase.position.z,
      targetShadowZ,
      11,
      delta,
    );
  }
  if (handle.shadowMaterial) {
    handle.shadowMaterial.opacity = THREE.MathUtils.damp(
      handle.shadowMaterial.opacity,
      targetShadowOpacity,
      10,
      delta,
    );
  }
  if (handle.lightMaterial) {
    handle.lightMaterial.color.set(
      state.pressed || state.hovered ? "#EEEAF5" : COLORS.keyCream,
    );
    handle.lightMaterial.emissiveIntensity = THREE.MathUtils.damp(
      handle.lightMaterial.emissiveIntensity,
      targetLight,
      10,
      delta,
    );
  }
  if (handle.whiteCapMaterial) {
    handle.whiteCapMaterial.emissiveIntensity = THREE.MathUtils.damp(
      handle.whiteCapMaterial.emissiveIntensity,
      effect * 0.2,
      10,
      delta,
    );
  }
  if (handle.blackMaterial) {
    handle.blackMaterial.color.set(
      state.pressed || state.hovered ? "#777594" : COLORS.keyEbony,
    );
    handle.blackMaterial.emissiveIntensity = THREE.MathUtils.damp(
      handle.blackMaterial.emissiveIntensity,
      targetBlack,
      10,
      delta,
    );
  }
  if (handle.markerMaterial) {
    handle.markerMaterial.opacity = THREE.MathUtils.damp(
      handle.markerMaterial.opacity,
      targetMarker,
      10,
      delta,
    );
  }
  return false;
}

function updateBookVisual(
  handle: BookVisualHandle,
  delta: number,
  state: {
    hovered: boolean;
    selected: boolean;
    pinned: boolean;
    focused: boolean;
  },
) {
  const group = handle.group;
  if (!group) return true;

  const focusedLift = state.focused ? 0.018 : 0;
  const targetZ =
    handle.interactive && state.selected
      ? 0.82
      : handle.interactive && state.hovered
        ? 0.34
        : state.pinned
          ? 0.16
          : 0;
  const targetY =
    handle.interactive && state.selected
      ? 0.18
      : handle.interactive && state.hovered
        ? 0.06
        : state.pinned
          ? 0.06
          : handle.interactive
            ? focusedLift
            : 0;
  const targetRotateZ =
    handle.interactive && (state.selected || state.hovered)
      ? -0.025
      : state.pinned
        ? -0.02
        : 0;
  const targetRotateY = handle.interactive && state.selected
    ? -0.17
    : handle.interactive && state.hovered
      ? -0.045
      : state.pinned
        ? -0.03
        : 0;
  const targetScale =
    handle.interactive && state.selected
      ? 1.055
      : handle.interactive && state.hovered
        ? 1.055
        : state.pinned
          ? 1.025
          : 1;
  const targetScaleZ =
    handle.interactive && (state.selected || state.hovered)
      ? 1.08
      : state.pinned
        ? 1.055
        : 1;
  const atRest =
    Math.abs(group.position.z - targetZ) < 0.0005 &&
    Math.abs(group.position.y - (handle.baseY + targetY)) < 0.0005 &&
    Math.abs(group.rotation.z - (handle.lean + targetRotateZ)) < 0.0005 &&
    Math.abs(group.rotation.y - targetRotateY) < 0.0005 &&
    Math.abs(group.scale.x - targetScale) < 0.0005 &&
    Math.abs(group.scale.z - targetScaleZ) < 0.0005;
  if (atRest) return true;

  group.position.z = THREE.MathUtils.damp(group.position.z, targetZ, 7.5, delta);
  group.position.y = THREE.MathUtils.damp(
    group.position.y,
    handle.baseY + targetY,
    9,
    delta,
  );
  group.rotation.z = THREE.MathUtils.damp(
    group.rotation.z,
    handle.lean + targetRotateZ,
    8,
    delta,
  );
  group.rotation.y = THREE.MathUtils.damp(
    group.rotation.y,
    targetRotateY,
    7,
    delta,
  );
  group.scale.x = THREE.MathUtils.damp(group.scale.x, targetScale, 10, delta);
  group.scale.y = THREE.MathUtils.damp(group.scale.y, targetScale, 10, delta);
  group.scale.z = THREE.MathUtils.damp(group.scale.z, targetScaleZ, 10, delta);
  return false;
}

function usePianoSynth() {
  const contextRef = useRef<AudioContext | null>(null);
  const voicesRef = useRef<Set<OscillatorNode>>(new Set());
  const activeOutputRef = useRef<GainNode | null>(null);
  const lastTriggerRef = useRef({ index: -1, at: 0 });

  const play = useCallback((index: number, force = false) => {
    if (typeof window === "undefined") return;
    const AudioContextConstructor =
      window.AudioContext ??
      (
        window as Window & {
          webkitAudioContext?: typeof AudioContext;
        }
      ).webkitAudioContext;
    if (!AudioContextConstructor) return;

    const context =
      contextRef.current ?? new AudioContextConstructor({ latencyHint: "interactive" });
    contextRef.current = context;
    if (context.state === "suspended") {
      void context.resume();
    }

    const note = pianoNoteForKey(index);
    const now = context.currentTime + 0.012;
    if (!force && now - lastTriggerRef.current.at < 0.045) return;
    lastTriggerRef.current = { index, at: now };

    if (activeOutputRef.current) {
      activeOutputRef.current.gain.cancelScheduledValues(now);
      activeOutputRef.current.gain.setTargetAtTime(0.0001, now, 0.012);
      activeOutputRef.current = null;
    }

    const output = context.createGain();
    output.gain.setValueAtTime(0.62, now);
    const filter = context.createBiquadFilter();
    filter.type = "lowpass";
    filter.Q.setValueAtTime(0.36, now);
    filter.frequency.setValueAtTime(
      Math.min(4800, note.frequency * 7),
      now,
    );
    filter.frequency.exponentialRampToValueAtTime(
      Math.max(620, note.frequency * 2),
      now + 1.45,
    );
    filter.connect(output);
    output.connect(context.destination);
    activeOutputRef.current = output;

    [
      {
        type: "sine" as OscillatorType,
        ratio: 1,
        gain: 0.42,
        detune: -1,
        decay: 2.15,
      },
      {
        type: "triangle" as OscillatorType,
        ratio: 1,
        gain: 0.18,
        detune: 2,
        decay: 2.05,
      },
      {
        type: "sine" as OscillatorType,
        ratio: 2,
        gain: 0.1,
        detune: 0,
        decay: 1.5,
      },
      {
        type: "sine" as OscillatorType,
        ratio: 3,
        gain: 0.045,
        detune: 1.5,
        decay: 1.05,
      },
      {
        type: "sine" as OscillatorType,
        ratio: 4,
        gain: 0.02,
        detune: -2,
        decay: 0.78,
      },
    ].forEach((voice) => {
      const oscillator = context.createOscillator();
      const voiceGain = context.createGain();
      oscillator.type = voice.type;
      oscillator.frequency.setValueAtTime(note.frequency * voice.ratio, now);
      oscillator.detune.setValueAtTime(voice.detune, now);
      voiceGain.gain.setValueAtTime(0.0001, now);
      voiceGain.gain.exponentialRampToValueAtTime(voice.gain, now + 0.006);
      voiceGain.gain.exponentialRampToValueAtTime(
        0.0001,
        now + voice.decay,
      );
      oscillator.connect(voiceGain);
      voiceGain.connect(filter);
      oscillator.start(now);
      oscillator.stop(now + voice.decay + 0.05);
      voicesRef.current.add(oscillator);
      oscillator.onended = () => {
        voicesRef.current.delete(oscillator);
        oscillator.disconnect();
        voiceGain.disconnect();
      };
    });

    window.setTimeout(() => {
      if (activeOutputRef.current === output) activeOutputRef.current = null;
      output.disconnect();
    }, 2350);
  }, []);

  useEffect(
    () => () => {
      voicesRef.current.forEach((voice) => {
        try {
          voice.stop();
        } catch {
          // The note may already have ended.
        }
      });
      voicesRef.current.clear();
      activeOutputRef.current?.disconnect();
      activeOutputRef.current = null;
      void contextRef.current?.close();
      contextRef.current = null;
    },
    [],
  );

  return play;
}

