function InteractiveSpineComponent({
  book,
  index,
  interactive,
  position,
  thickness,
  height,
  depth,
  lean,
  registerBook,
  onTogglePinned,
  onHover,
  onOpen,
}: InteractiveSpineProps) {
  const group = useRef<THREE.Group>(null);
  const spine = useMemo(
    () => createSpineTexture(book, index, position[1]),
    [book, index, position],
  );
  const geometry = useMemo(
    () => createBookVolumeGeometry(thickness, height, depth),
    [depth, height, thickness],
  );
  const baseColor =
    BOOK_COLORS[book.id] ??
    book.spine ??
    FILLER_PALETTE[index % FILLER_PALETTE.length] ??
    COLORS.cabinet;
  const coverMaterial = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: baseColor,
        roughness: 0.64,
        metalness: 0.01,
      }),
    [baseColor],
  );
  const spineMaterial = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        map: spine,
        roughness: 0.58,
        metalness: 0.01,
      }),
    [spine],
  );
  const paperMaterial = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: "#F6EFE5",
        roughness: 0.9,
        metalness: 0,
      }),
    [],
  );
  const bandMaterial = useMemo(
    () =>
      new THREE.MeshStandardMaterial({
        color: "#F7E9D9",
        roughness: 0.62,
        metalness: 0.02,
      }),
    [],
  );
  useEffect(
    () => () => {
      spine.dispose();
      coverMaterial.dispose();
      spineMaterial.dispose();
      paperMaterial.dispose();
      bandMaterial.dispose();
    },
    [bandMaterial, coverMaterial, paperMaterial, spine, spineMaterial],
  );

  useEffect(() => {
    registerBook(book.id, {
      id: book.id,
      interactive,
      baseY: position[1],
      lean,
      group: group.current,
    });
    return () => registerBook(book.id, null);
  }, [book.id, interactive, lean, position[1], registerBook]);

  const handleOver = (event: ThreeEvent<PointerEvent>) => {
    if (!interactive) return;
    event.stopPropagation();
    onHover(book);
    document.body.style.cursor = "pointer";
  };
  const handleOut = (event: ThreeEvent<PointerEvent>) => {
    if (!interactive) return;
    event.stopPropagation();
    onHover(null);
    document.body.style.cursor = "";
  };
  const handleDecorativeEnter = (event: ThreeEvent<PointerEvent>) => {
    if (interactive) return;
    event.stopPropagation();
    document.body.style.cursor = "pointer";
  };
  const handleDecorativeOut = (event: ThreeEvent<PointerEvent>) => {
    if (interactive) return;
    event.stopPropagation();
    document.body.style.cursor = "";
  };
  const handleBookClick = (event: ThreeEvent<MouseEvent>) => {
    event.stopPropagation();
    if (interactive) {
      onOpen(book);
    } else {
      onTogglePinned(book.id);
    }
  };

  return (
    <group ref={group} position={position}>
      <mesh
        position={[0, 0, -0.018]}
        material={paperMaterial}
        castShadow
        receiveShadow
      >
        <boxGeometry args={[thickness * 0.9, height + 0.012, depth * 0.9]} />
      </mesh>
      <mesh
        geometry={geometry}
        material={coverMaterial}
        castShadow
        receiveShadow
        onPointerOver={interactive ? handleOver : handleDecorativeEnter}
        onPointerOut={interactive ? handleOut : handleDecorativeOut}
        onClick={handleBookClick}
      />
      <mesh
        position={[0, 0, depth / 2 + 0.004]}
        material={spineMaterial}
        castShadow
        onPointerOver={interactive ? handleOver : handleDecorativeEnter}
        onPointerOut={interactive ? handleOut : handleDecorativeOut}
        onClick={handleBookClick}
      >
        <planeGeometry args={[thickness * 0.84, height * 0.93]} />
      </mesh>
      {[-1, 1].map((direction) => (
        <mesh
          key={direction}
          position={[
            0,
            direction * Math.max(0, height / 2 - 0.105),
            depth / 2 + 0.014,
          ]}
          material={bandMaterial}
          castShadow
          onPointerOver={interactive ? handleOver : handleDecorativeEnter}
          onPointerOut={interactive ? handleOut : handleDecorativeOut}
          onClick={handleBookClick}
        >
          <boxGeometry args={[thickness * 0.84, 0.016, 0.018]} />
        </mesh>
      ))}
      <mesh
        position={[0, 0, depth / 2 + 0.045]}
        onPointerOver={interactive ? handleOver : handleDecorativeEnter}
        onPointerOut={interactive ? handleOut : handleDecorativeOut}
        onClick={handleBookClick}
      >
        <planeGeometry args={[thickness + 0.075, height + 0.07]} />
        <meshBasicMaterial transparent opacity={0} depthWrite={false} />
      </mesh>
    </group>
  );
}

const InteractiveSpine = memo(InteractiveSpineComponent);

function createBookVolumeGeometry(
  thickness: number,
  height: number,
  depth: number,
) {
  const inset = Math.min(0.022, thickness * 0.11);
  const shape = createRoundedRectShape(
    Math.max(0.08, thickness - inset * 2),
    Math.max(0.2, height - inset * 0.9),
    Math.min(0.038, thickness * 0.28),
  );
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth: Math.max(0.18, depth - 0.04),
    bevelEnabled: true,
    bevelThickness: 0.014,
    bevelSize: 0.012,
    bevelSegments: 3,
    curveSegments: 8,
  });
  geometry.translate(0, 0, -(depth - 0.04) / 2);
  geometry.computeVertexNormals();
  return geometry;
}

function createRoundedRectShape(
  width: number,
  height: number,
  radius: number,
) {
  const safeRadius = Math.min(radius, width / 2, height / 2);
  const left = -width / 2;
  const right = width / 2;
  const bottom = -height / 2;
  const top = height / 2;
  const shape = new THREE.Shape();

  shape.moveTo(left + safeRadius, bottom);
  shape.lineTo(right - safeRadius, bottom);
  shape.quadraticCurveTo(right, bottom, right, bottom + safeRadius);
  shape.lineTo(right, top - safeRadius);
  shape.quadraticCurveTo(right, top, right - safeRadius, top);
  shape.lineTo(left + safeRadius, top);
  shape.quadraticCurveTo(left, top, left, top - safeRadius);
  shape.lineTo(left, bottom + safeRadius);
  shape.quadraticCurveTo(left, bottom, left + safeRadius, bottom);
  return shape;
}

