import {
  ArrowLeft,
  BookOpen,
  Eraser,
  Highlighter,
  Languages,
  Underline,
} from "lucide-react";
import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type MouseEvent as ReactMouseEvent,
} from "react";
import { Navigate, useNavigate, useParams } from "react-router-dom";
import {
  normalizeReaderWord,
  tokenizeReaderText,
} from "../../lib/readerWords";
import {
  loadReaderAnnotations,
  saveReaderAnnotations,
  splitReaderSentences,
  type ReaderAnnotationType,
  type ReaderAnnotations,
} from "../../lib/readerAnnotations";
import {
  allReaderBooks,
  readerBookById,
  type ReaderBook,
} from "../../lib/readerLibrary";
import { WordLookupFolder } from "../reader/WordLookupFolder";
import WarmTooltip, {
  WarmTooltipGroup,
} from "../reactbits/vendor/WarmTooltip/WarmTooltip";
import { SplitText } from "../reactbits/vendor";
import "./immersive-reader.css";

interface SelectionState {
  text: string;
  contextBefore: string;
  contextAfter: string;
  x: number;
  y: number;
  drawer: boolean;
}

const ANNOTATION_TOOLS = [
  { mode: "lookup", icon: Languages, label: "查词" },
  { mode: "underline", icon: Underline, label: "下划线" },
  { mode: "highlight", icon: Highlighter, label: "荧光笔" },
  { mode: "sentence", icon: Highlighter, label: "句子" },
] as const;

function splitParagraphs(value: string) {
  return value
    .split(/\n+/)
    .map((paragraph) => paragraph.trim())
    .filter(Boolean);
}

function sentenceContext(paragraph: string, selected: string) {
  const index = paragraph.indexOf(selected);
  if (index < 0) {
    return {
      before: paragraph.slice(0, 180),
      after: "",
    };
  }
  return {
    before: paragraph.slice(Math.max(0, index - 220), index),
    after: paragraph.slice(
      index + selected.length,
      index + selected.length + 220,
    ),
  };
}

function bookOpeningCover(book: ReaderBook) {
  if (typeof document === "undefined") return "";
  const canvas = document.createElement("canvas");
  canvas.width = 1200;
  canvas.height = 760;
  const context = canvas.getContext("2d");
  if (!context) return "";

  const gradient = context.createLinearGradient(
    0,
    0,
    canvas.width,
    canvas.height,
  );
  gradient.addColorStop(0, book.spine);
  gradient.addColorStop(1, "#171d20");
  context.fillStyle = gradient;
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "rgba(255,255,255,.1)";
  context.beginPath();
  context.arc(930, 160, 260, 0, Math.PI * 2);
  context.fill();
  context.fillStyle = "#f5c78f";
  context.font = "600 22px Segoe UI";
  context.fillText("INKFLOW · OPEN READING", 90, 120);
  context.fillStyle = "#fff9ee";
  context.font = "600 68px Georgia";
  context.fillText(book.title, 88, 300, 980);
  context.font = "500 28px Segoe UI";
  context.fillStyle = "rgba(255,255,255,.68)";
  context.fillText(book.author, 90, 350, 840);
  context.font = "400 28px Georgia";
  context.fillStyle = "rgba(255,255,255,.86)";
  const excerpt = splitParagraphs(book.source)[0]?.slice(0, 190) ?? "";
  let line = "";
  let y = 470;
  for (const word of excerpt.split(/\s+/)) {
    const next = line ? `${line} ${word}` : word;
    if (context.measureText(next).width > 960) {
      context.fillText(line, 90, y);
      line = word;
      y += 44;
    } else {
      line = next;
    }
    if (y > 650) break;
  }
  if (line && y <= 650) context.fillText(line, 90, y);

  return canvas.toDataURL("image/webp", 0.92);
}

export function BookReaderPage() {
  const { bookId } = useParams();
  const navigate = useNavigate();
  const sourceRef = useRef<HTMLDivElement>(null);
  const [showTranslation, setShowTranslation] = useState(false);
  const [selection, setSelection] = useState<SelectionState | null>(null);
  const [annotationMode, setAnnotationMode] = useState<
    "lookup" | "underline" | "highlight" | "sentence" | "eraser"
  >("lookup");
  const [annotations, setAnnotations] = useState<ReaderAnnotations>({});

  const book = useMemo(() => readerBookById(bookId ?? ""), [bookId]);

  const sourceParagraphs = useMemo(
    () => splitParagraphs(book?.source ?? ""),
    [book],
  );
  const translationParagraphs = useMemo(
    () => splitParagraphs(book?.translation ?? ""),
    [book],
  );
  useEffect(() => {
    setSelection(null);
    setAnnotations(bookId ? loadReaderAnnotations(bookId) : {});
  }, [bookId]);

  if (!book) return <Navigate to="/library" replace />;

  const openWordLookup = (
    event: ReactMouseEvent<HTMLButtonElement>,
    paragraph: string,
    word: string,
    annotationKey: string,
  ) => {
    if (annotationMode !== "lookup") {
      event.stopPropagation();
      toggleAnnotation(
        annotationKey,
        annotationMode === "eraser"
          ? null
          : annotationMode === "sentence"
            ? "sentence"
            : annotationMode,
      );
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const context = sentenceContext(paragraph, word);
    const drawer = window.innerWidth < 720;
    setSelection({
      text: word,
      contextBefore: context.before,
      contextAfter: context.after,
      x: Math.min(
        window.innerWidth - 400,
        Math.max(14, rect.left + rect.width / 2 - 190),
      ),
      y: Math.min(window.innerHeight - 520, rect.bottom + 12),
      drawer,
    });
  };

  const toggleAnnotation = (
    key: string,
    type: ReaderAnnotationType | null,
  ) => {
    setAnnotations((current) => {
      const next = { ...current };
      if (!type || next[key] === type) delete next[key];
      else next[key] = type;
      if (bookId) saveReaderAnnotations(bookId, next);
      return next;
    });
  };

  const captureSelection = () => {
    const browserSelection = window.getSelection();
    if (
      !browserSelection ||
      browserSelection.isCollapsed ||
      !sourceRef.current
    ) {
      return;
    }
    const text = browserSelection.toString().replace(/\s+/g, " ").trim();
    if (!text || text.length > 220) {
      setSelection(null);
      return;
    }
    const range = browserSelection.getRangeAt(0);
    const ancestor =
      range.commonAncestorContainer.nodeType === Node.ELEMENT_NODE
        ? (range.commonAncestorContainer as Element)
        : range.commonAncestorContainer.parentElement;
    const paragraph = ancestor?.closest("p");
    if (!paragraph || !sourceRef.current.contains(paragraph)) return;

    const paragraphText = paragraph.textContent ?? "";
    const context = sentenceContext(paragraphText, text);
    const rect = range.getBoundingClientRect();
    const drawer = window.innerWidth < 720;
    setSelection({
      text,
      contextBefore: context.before,
      contextAfter: context.after,
      x: Math.min(
        window.innerWidth - 400,
        Math.max(14, rect.left + rect.width / 2 - 190),
      ),
      y: Math.min(window.innerHeight - 520, rect.bottom + 12),
      drawer,
    });
  };

  return (
    <article className="immersive-reader">
      <header className="immersive-reader__header">
        <button
          type="button"
          onClick={() => navigate("/library")}
          aria-label="返回书架"
        >
          <ArrowLeft size={18} />
        </button>
        <div>
          <span className="eyebrow">{book.author}</span>
          <SplitText
            tag="h1"
            text={book.title}
            className="immersive-reader__title"
            delay={52}
            duration={0.58}
            ease="power3.out"
            splitType="words"
            from={{ opacity: 0, y: 24 }}
            to={{ opacity: 1, y: 0 }}
            threshold={0}
            rootMargin="0px"
            textAlign="left"
          />
          <p>{book.zhTitle}</p>
        </div>
        <button
          type="button"
          className={showTranslation ? "is-active" : ""}
          onClick={() => setShowTranslation((value) => !value)}
          aria-pressed={showTranslation}
        >
          <Languages size={16} />
          中文
        </button>
      </header>

      <div className="immersive-reader__meta">
        <span>{sourceParagraphs.length} paragraphs</span>
        <span>Oxford Learner&apos;s · dictionary lookup</span>
        <span>点击任意英文单词查词 · 选中文本使用 AI 解释</span>
      </div>

      <WarmTooltipGroup delay={300} warmWindow={220} travel={220}>
        <div className="reader-annotation-toolbar" aria-label="文章标注工具">
          {ANNOTATION_TOOLS.map(({ mode, icon: Icon, label }) => (
            <WarmTooltip
              content={label}
              side="bottom"
              surfaceColor="#f5efe3"
              inkColor="#2a231e"
              radius={7}
              key={mode}
            >
              <button
                type="button"
                className={annotationMode === mode ? "is-active" : ""}
                aria-label={label}
                onClick={() => setAnnotationMode(mode)}
              >
                <Icon size={14} />
                {label}
              </button>
            </WarmTooltip>
          ))}
          <WarmTooltip
            content="擦除标注"
            side="bottom"
            surfaceColor="#f5efe3"
            inkColor="#2a231e"
            radius={7}
          >
            <button
              type="button"
              className={annotationMode === "eraser" ? "is-active" : ""}
              aria-label="擦除标注"
              onClick={() => setAnnotationMode("eraser")}
            >
              <Eraser size={14} />
              擦除
            </button>
          </WarmTooltip>
          <WarmTooltip
            content="清除全部标注"
            side="bottom"
            surfaceColor="#f5efe3"
            inkColor="#2a231e"
            radius={7}
          >
            <button
              type="button"
              aria-label="清除全部标注"
              onClick={() => {
                setAnnotations({});
                if (bookId) saveReaderAnnotations(bookId, {});
              }}
            >
              清除
            </button>
          </WarmTooltip>
        </div>
      </WarmTooltipGroup>

      <main
        ref={sourceRef}
        className="immersive-reader__text"
        onMouseUp={captureSelection}
        onKeyUp={captureSelection}
      >
        {sourceParagraphs.map((paragraph, index) => (
          <section key={`${book.id}-${index}`}>
            <p>
              {splitReaderSentences(paragraph).map(
                (sentence, sentenceIndex) => {
                  const sentenceKey = `sentence:${index}:${sentenceIndex}`;
                  const sentenceType = annotations[sentenceKey];
                  return (
                    <span
                      key={sentenceKey}
                      className={cnReaderAnnotation(
                        "immersive-reader__sentence",
                        sentenceType &&
                          `is-${sentenceType}`,
                      )}
                      onClick={() => {
                        if (
                          annotationMode !== "sentence" &&
                          annotationMode !== "eraser"
                        ) {
                          return;
                        }
                        toggleAnnotation(
                          sentenceKey,
                          annotationMode === "eraser"
                            ? null
                            : "sentence",
                        );
                      }}
                    >
                      {tokenizeReaderText(sentence).map(
                        (token, tokenIndex) => {
                          if (!token.isWord) {
                            return (
                              <span key={`${sentenceIndex}-${tokenIndex}`}>
                                {token.value}
                              </span>
                            );
                          }
                          const wordKey = `word:${index}:${sentenceIndex}:${tokenIndex}:${normalizeReaderWord(token.value)}`;
                          return (
                            <button
                              key={wordKey}
                              type="button"
                              className={cnReaderAnnotation(
                                "immersive-reader__word",
                                annotations[wordKey] &&
                                  `is-${annotations[wordKey]}`,
                              )}
                              onClick={(event) =>
                                openWordLookup(
                                  event,
                                  paragraph,
                                  token.value,
                                  wordKey,
                                )
                              }
                            >
                              {token.value}
                            </button>
                          );
                        },
                      )}
                      {sentenceIndex <
                      splitReaderSentences(paragraph).length - 1
                        ? " "
                        : null}
                    </span>
                  );
                },
              )}
            </p>
            {showTranslation && translationParagraphs[index] && (
              <p className="immersive-reader__translation">
                {translationParagraphs[index]}
              </p>
            )}
          </section>
        ))}
      </main>

      <footer className="immersive-reader__footer">
        <button type="button" onClick={() => navigate("/library")}>
          <BookOpen size={15} />
          书架
        </button>
        <span>
          {Math.max(
            1,
            allReaderBooks().findIndex((entry) => entry.id === book.id) + 1,
          )}{" "}
          / {allReaderBooks().length}
        </span>
      </footer>

      {selection && (
        <WordLookupFolder
          word={selection.text}
          contextBefore={selection.contextBefore}
          contextAfter={selection.contextAfter}
          x={selection.x}
          y={selection.y}
          drawer={selection.drawer}
          bookId={book.id}
          bookLabel={`${book.title} · ${book.zhTitle}`}
          onClose={() => setSelection(null)}
        />
      )}
    </article>
  );
}

function cnReaderAnnotation(
  ...values: Array<string | false | null | undefined>
) {
  return values.filter(Boolean).join(" ");
}
