import type { ReaderBook } from "../../lib/readerLibrary";

export const SHELF_LEVELS = [
  { number: "01", english: "Reading Now", chinese: "当前阅读" },
  { number: "02", english: "My Collection", chinese: "收藏书籍" },
  { number: "03", english: "Language Garden", chinese: "语言花园" },
  { number: "04", english: "Memories", chinese: "学习记录" },
] as const;

const SHELF_CAPACITY = [3, 3, 2, 6] as const;

export interface ShelfRow {
  number: string;
  english: string;
  chinese: string;
  books: ReaderBook[];
}

export function createShelfRows(books: ReaderBook[]): ShelfRow[] {
  let cursor = 0;

  return SHELF_LEVELS.map((level, rowIndex) => {
    const capacity = SHELF_CAPACITY[rowIndex] ?? 0;
    const rowBooks = books.slice(cursor, cursor + capacity);
    cursor += rowBooks.length;

    return {
      ...level,
      books: [...rowBooks],
    };
  });
}
