import {
  BookmarkPlus,
  Languages,
  LoaderCircle,
  Sparkles,
  Volume2,
  X,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import type { LanguageInsight } from "@inkflow/shared";
import { fallbackInsight } from "../../data/demo";
import { api } from "../../lib/api";
import { cn } from "../../lib/cn";
import { useInkFlow } from "../../store/inkflow";
import { useVocabulary } from "../../store/vocabulary";
import "./word-lookup-folder.css";

type LookupKind = "dictionary" | "ai";

export interface WordLookupFolderProps {
  word: string;
  contextBefore: string;
  contextAfter: string;
  x: number;
  y: number;
  drawer: boolean;
  bookId: string;
  bookLabel: string;
  onClose: () => void;
}

function speak(text: string) {
  if (typeof window === "undefined" || !("speechSynthesis" in window)) return;
  window.speechSynthesis.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = "en-US";
  utterance.rate = 0.86;
  window.speechSynthesis.speak(utterance);
}

export function WordLookupFolder({
  word,
  contextBefore,
  contextAfter,
  x,
  y,
  drawer,
  bookId,
  bookLabel,
  onClose,
}: WordLookupFolderProps) {
  const panelRef = useRef<HTMLElement>(null);
  const showToast = useInkFlow((state) => state.showToast);
  const addWord = useVocabulary((state) => state.addInsight);
  const [kind, setKind] = useState<LookupKind>("dictionary");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<LanguageInsight | null>(null);

  const requestKey = useMemo(
    () => `${kind}:${word}:${bookId}`,
    [bookId, kind, word],
  );

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setResult(null);

    const request =
      kind === "dictionary"
        ? api
            .dictionary(word)
            .then((response) => response.insight)
            .catch(() => fallbackInsight(word))
        : api
            .insight({
              noteId: `book-${bookId}`,
              pageId: bookId,
              selectedText: word,
              contextBefore,
              contextAfter,
              locale: "zh-CN",
              sourceSpan: {
                noteId: `book-${bookId}`,
                pageId: bookId,
                blockId: "reader-lookup",
              },
            })
            .then((response) => response.insight)
            .catch(() => fallbackInsight(word));

    void request.then((nextResult) => {
      if (!cancelled) setResult(nextResult);
    }).finally(() => {
      if (!cancelled) setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [bookId, contextAfter, contextBefore, requestKey, kind, word]);

  useEffect(() => {
    const onPointerDown = (event: PointerEvent) => {
      if (
        panelRef.current &&
        !panelRef.current.contains(event.target as Node)
      ) {
        onClose();
      }
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
    };
    window.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("keydown", onKeyDown);
    return () => {
      window.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [onClose]);

  const addToCorpus = async () => {
    if (!result) return;
    try {
      const response = await api.addCorpus({
        insight: result,
        sourceLabel: bookLabel,
        tags: ["reading", bookId],
      });
      useInkFlow.setState((state) => ({
        corpus: [
          response.entry,
          ...state.corpus.filter((entry) => entry.id !== response.entry.id),
        ],
      }));
      showToast(`已收入语料：${result.term}`);
    } catch {
      showToast("语料保存失败，请稍后重试。");
    }
  };

  const addToWordbook = () => {
    if (!result) return;
    addWord(result, bookLabel, contextBefore);
    showToast(`已加入单词本：${result.term}`);
  };

  return createPortal(
    <aside
      ref={panelRef}
      className={cn(
        "word-lookup-folder",
        drawer && "word-lookup-folder--drawer",
      )}
      style={drawer ? undefined : { left: x, top: y }}
      role="dialog"
      aria-label={`${word} 的牛津词典查询`}
    >
      <span className="word-lookup-folder__back" aria-hidden="true" />
      <span className="word-lookup-folder__paper" aria-hidden="true" />
      <div className="word-lookup-folder__front">
        <header>
          <div>
            <small>Oxford Learner&apos;s</small>
            <strong>{word}</strong>
          </div>
          <button type="button" onClick={onClose} aria-label="关闭词典">
            <X size={15} />
          </button>
        </header>

        <div className="word-lookup-folder__tabs">
          <button
            type="button"
            className={kind === "dictionary" ? "is-active" : ""}
            onClick={() => setKind("dictionary")}
          >
            <Languages size={13} />
            牛津词典
          </button>
          <button
            type="button"
            className={kind === "ai" ? "is-active" : ""}
            onClick={() => setKind("ai")}
          >
            <Sparkles size={13} />
            AI 解释
          </button>
        </div>

        <div className="word-lookup-folder__result">
          {loading ? (
            <span className="word-lookup-folder__loading">
              <LoaderCircle size={16} />
              正在查询…
            </span>
          ) : result ? (
            <>
              <div className="word-lookup-folder__meaning">
                <strong>{result.meaningsZh.join("；")}</strong>
                <p>{result.definitionEn}</p>
              </div>
              {result.collocations.length > 0 && (
                <div className="word-lookup-folder__chips">
                  {result.collocations.slice(0, 4).map((item) => (
                    <span key={item}>{item}</span>
                  ))}
                </div>
              )}
              {result.examples[0] && (
                <blockquote>
                  {result.examples[0].text}
                  {result.examples[0].translationZh && (
                    <small>{result.examples[0].translationZh}</small>
                  )}
                </blockquote>
              )}
            </>
          ) : (
            <span>暂时没有结果。</span>
          )}
        </div>

        <footer>
          <button type="button" onClick={() => speak(word)}>
            <Volume2 size={14} />
            朗读
          </button>
          <button type="button" onClick={() => void addToCorpus()} disabled={!result}>
            <BookmarkPlus size={14} />
            加入语料
          </button>
          <button type="button" onClick={addToWordbook} disabled={!result}>
            加入单词本
          </button>
        </footer>
      </div>
    </aside>,
    document.body,
  );
}
